// Browser sources only, and the authority on what ships to a browser.
//
// Node's globals are deliberately absent here. `tsconfig.json` beside this one
// admits them, because the tests and build tooling are Node programs, and it
// has to cover them for the language service to resolve them at all. That
// makes this the file that decides what `src` may reference: a source file
// that reaches for `process` compiles under the wide config and fails here.
{
  "extends": "@lasvegasfortransit/typescript-config/browser.json",
  "compilerOptions": {
    "useDefineForClassFields": true,
    "allowImportingTsExtensions": true,
    "types": ["vite/client"],
    // Adoption debt, not a deliberate stance: the standard turns both flags
    // on unconditionally, and this app has never been checked under either.
    // Pay this down package by package rather than in the same change that
    // swaps in the shared config.
    "exactOptionalPropertyTypes": false,
    "noUncheckedIndexedAccess": false
  },
  "include": ["src"]
}

